// @ts-nocheck
/* eslint-disable */
/**
 * Report page engine. GENERATED by tools/sync-report.mjs from web/pages/report.xhtml (+ web/resources/mock/report_mock.json) — do not edit; change the script and run `npm run report:sync`.
 *
 * The page script of the Java screen, same behaviour line by line: the report list (groups, search, permission filter), the filter
 * panel of the selected report (dd/MM/yyyy date ranges, selects with options from master data, required filters) and the call that
 * opens the report PDF in a new tab.
 *
 * WHY it is imperative DOM code and not Angular components: see engine.ts of the Dashboard — the Java page draws its HTML from data as
 * strings; porting it 1:1 is what guarantees the screen, texts and states are identical to the production system.
 * "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java file (all of it lives in tools/sync-report.mjs):
 *   - the environment is injected (ReportEnv): the context path, fetch, window.open, SweetAlert and the value the server rendered
 *     into the page with EL (commonBean.reportPermJson);
 *   - the script waited for DOMContentLoaded: the engine plays that event itself, after the script ran (see port-kit.mjs);
 *   - listeners / timers added through listen() / tmo() and the response guard are removed by the function returned from startReport().
 */

export interface ReportEnv {
  /** #{request.contextPath}: where the data file and the master data are served from ("/triplesale" in Java) */
  ctx: string;
  /** fetch for ctx + '/resources/mock/report_mock.json', the master data (/board/chat-master-data, /board/employees) */
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
  /** window.open(url, '_blank') — null when the browser blocked the new tab */
  open: (url: string, target?: string) => { closed?: boolean } | null;
  /** SweetAlert v2 (js/sweetalert/sweetalertv1.min.js) */
  swal: (options: Record<string, unknown>) => Promise<unknown>;
  /** the JSON values commonBean rendered into the page with EL: 'reportPermJson' = { <report code>: boolean } */
  initial: (name: string) => any;
}

export function startReport(env: ReportEnv): () => void {
  var destroyed = false;
  var disposers = [];
  var timers = [];
  var observers = [];
  function listen(target, type, fn, opts) {
    target.addEventListener(type, fn, opts);
    disposers.push(function () { target.removeEventListener(type, fn, opts); });
  }
  function tmo(fn, ms) { var h = setTimeout(function () { if (!destroyed) { fn(); } }, ms); timers.push(h); return h; }
  function track(o) { observers.push(o); return o; }
  /* document.readyState / DOMContentLoaded / load of the page the script was written for (see the generator) */
  var readyState = 'loading';
  var readyQueue = [];
  var loadQueue = [];
  function onReady(fn) { if (readyState === 'loading') { readyQueue.push(fn); } else { tmo(fn, 0); } }
  function onLoad(fn) { if (readyState !== 'complete') { loadQueue.push(fn); } else { tmo(fn, 0); } }
  function runQueue(queue, type) {
    queue.splice(0).forEach(function (fn) {
      try { fn.call(type === 'load' ? window : document, new Event(type)); } catch (e) { console.error(e); }
    });
  }

  /* Nothing that is still in flight when the screen is left may repaint it: after destroy() a request never settles. */
  var rawFetch = env.fetch;
  var never = function () { return new Promise(function () {}); };
  var guardResponse = function (r) {
    return {
      ok: r.ok, status: r.status, statusText: r.statusText, headers: r.headers, url: r.url,
      clone: function () { return guardResponse(r.clone()); },
      json: function () { return r.json().then(function (v) { return destroyed ? never() : v; }); },
      text: function () { return r.text().then(function (v) { return destroyed ? never() : v; }); },
      blob: function () { return r.blob().then(function (v) { return destroyed ? never() : v; }); },
      arrayBuffer: function () { return r.arrayBuffer().then(function (v) { return destroyed ? never() : v; }); }
    };
  };
  env = Object.assign({}, env, {
    fetch: function (a, b) {
      if (destroyed) { return never(); }
      return rawFetch(a, b).then(
        function (r) { return destroyed ? never() : guardResponse(r); },
        function (e) { return destroyed ? never() : Promise.reject(e); });
    }
  });

(function () {
                "use strict";

                /* ★ จุดเดียวที่ต้องแก้เมื่อเปลี่ยนไปใช้ API จริง */
                var CTX = env.ctx;
                var RPT_DATA_URL = CTX + '/resources/mock/report_mock.json';

                var DATA = null, current = null, kw = '';

                /* ★ 19/08/2026 — สิทธิ์รายงานตามทะเบียน Role (Report_<CODE>_View)
                   ฝั่ง server เป็นคนบอกว่ารายงานไหนเห็นได้ (ดู CommonBean.getReportPermJson)
                   — หน้าเว็บแค่ซ่อน/ปิดปุ่มให้ตรงกัน ส่วนด่านจริงอยู่ที่ ReportPdfServlet */
                var RPT_PERM = env.initial('reportPermJson');
                function canReport(code) {
                    return !!RPT_PERM && RPT_PERM[code] === true;   /* อยู่ใน CDATA ใช้ && ตรง ๆ ได้ */
                }

                function $(id) { return document.getElementById(id); }
                function esc(s) {
                    return String(s === null || s === undefined ? '' : s)
                            .replace(/&/g, '&amp;').replace(/"/g, '&quot;')
                            .replace(/</g, '&lt;').replace(/>/g, '&gt;');
                }

                function matched(r) {
                    var k = kw.trim().toLowerCase();
                    if (!k) { return true; }
                    return (r.code + ' ' + r.name).toLowerCase().indexOf(k) !== -1;
                }

                function renderGroups() {
                    var box = $('rptGroups');
                    if (!box || !DATA) { return; }
                    var html = '';
                    (DATA.groups || []).forEach(function (g) {
                        var list = (g.reports || []).filter(matched).filter(function (r) {
                            return canReport(r.code);   /* ★ ไม่มีสิทธิ์ = ไม่ต้องเห็นรายงานนี้ */
                        });
                        if (!list.length && kw.trim()) { return; }   /* ค้นหาแล้วไม่เจอในกลุ่มนี้ → ซ่อนทั้งการ์ด */
                        html += '<div class="rpt-card">' +
                                    '<div class="rpt-card-hd">' + esc(g.title) + '</div>' +
                                    (list.length ? list.map(function (r) {
                                        var on = current && current.code === r.code;
                                        return '<div class="rpt-item' + (on ? ' on' : '') + '" data-code="' + esc(r.code) + '"' +
                                                    ' role="button" tabindex="0" title="' + esc(r.name) + '">' +
                                                '<span class="code">' + esc(r.code) + '</span>' +
                                                '<span class="name">' + esc(r.name) + '</span>' +
                                                '<i class="fa-solid fa-chevron-right go"></i>' +
                                            '</div>';
                                    }).join('') : '<div class="rpt-empty">ไม่มีรายงานในกลุ่มนี้</div>') +
                                '</div>';
                    });
                    box.innerHTML = html || '<div class="rpt-card"><div class="rpt-empty">' +
                            '<i class="fa-regular fa-folder-open" style="display:block;font-size:26px;margin-bottom:8px;"></i>' +
                            'ไม่พบรายงานที่ค้นหา</div></div>';

                    Array.prototype.forEach.call(box.querySelectorAll('.rpt-item'), function (el) {
                        function pick() { select(el.getAttribute('data-code')); }
                        el.addEventListener('click', pick);
                        el.addEventListener('keydown', function (e) {
                            if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pick(); }
                        });
                    });
                }

                function findReport(code) {
                    var found = null;
                    (DATA.groups || []).forEach(function (g) {
                        (g.reports || []).forEach(function (r) { if (r.code === code) { found = r; } });
                    });
                    return found;
                }

                function select(code) {
                    current = findReport(code);
                    renderGroups();
                    renderSide();
                }

                /* ★ 17/08/2026 — ช่องวันที่แสดงเป็น dd/MM/yyyy ตามที่ user สั่งตอนนั้น
                   เดิมใช้ <input type="date"> ซึ่ง "รูปแบบที่เห็น" ถูกกำหนดโดย locale ของเบราว์เซอร์
                   บังคับเองไม่ได้ (เครื่องที่ตั้งเป็น en-US จะเห็น mm/dd/yyyy)
                   จึงเปลี่ยนเป็น input text + class ods-date = ปฏิทินกลางของระบบ (open_down_select.js)
                   และ MutationObserver ของสคริปต์นั้นจะเสริมปฏิทินให้เองแม้ช่องจะถูก render ทีหลัง (renderSide)
                   ★ ค่าที่ "ส่งออก" ยังเป็น yyyy-MM-dd เหมือนเดิม (แปลงตอน collectFilters)
                     servlet/ระบบรายงานจึงไม่ต้องแก้อะไรเลย
                   (ระหว่างทางเคยแกว่งไป mm/dd/yyyy ช่วง 27/08 แล้วกลับมา dd/MM/yyyy อีกครั้ง 04/09 —
                    ให้ตรงกับ open_down_select.js getVal/setVal เสมอ ทั้งสองฝั่งต้องแก้คู่กัน) */
                function isoToMdy(s) {
                    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || '').trim());
                    return m ? (m[3] + '/' + m[2] + '/' + m[1]) : '';
                }
                /* ★ 17/08/2026 — ค่าเริ่มต้นของช่วงวันที่กำหนดแบบ "สัมพัทธ์" ได้ใน json
                   รองรับ: today | today-30 | today+7 | 2026-02-01 (ระบุตรง ๆ ก็ยังได้เหมือนเดิม)
                   ทำเป็นสูตรแทนการ hardcode วันที่ เพราะวันที่ตายตัวจะเก่าไปเองทุกวัน
                   และรายงานตัวอื่นเลือกช่วงของตัวเองได้โดยไม่ต้องแก้ไฟล์นี้ */
                function resolveDefaultDate(v) {
                    var s = String(v || '').trim();
                    if (!s) { return ''; }
                    var m = /^today\s*([+-]\s*\d+)?$/i.exec(s);
                    if (!m) { return s; }                       /* เป็น yyyy-MM-dd อยู่แล้ว */
                    var d = new Date();
                    if (m[1]) { d.setDate(d.getDate() + parseInt(m[1].replace(/\s+/g, ''), 10)); }
                    return d.getFullYear() + '-' + ('0' + (d.getMonth() + 1)).slice(-2)
                            + '-' + ('0' + d.getDate()).slice(-2);
                }

                function mdyToIso(s) {
                    // ★ 04/09: dd/MM/yyyy — รับทั้งปี 2 หลักและ 4 หลักกันพัง (เหมือน open_down_select.js getVal())
                    var m = /^(\d{1,2})\/(\d{1,2})\/(\d{2}|\d{4})$/.exec(String(s || '').trim());
                    if (!m) { return ''; }
                    var d = ('0' + m[1]).slice(-2), mo = ('0' + m[2]).slice(-2);
                    var yyyy = m[3].length === 4 ? m[3] : String(2000 + (+m[3]));
                    return yyyy + '-' + mo + '-' + d;
                }

                /* ★ นิยามตัวกรอง: รายงานแต่ละตัวทับ filterDefs กลางได้ (report.filterDefs)
                   ใช้กับรายงานที่ตัวเลือกต้องตรงกับระบบรายงานเดิมเป๊ะ ๆ เช่น CRMG10 ที่ค่าของ
                   "เรียงลำดับ" ต้องเป็นชื่อคอลัมน์จริง ไม่ใช่ค่าที่เราตั้งเองตอนทำ mockup */
                function defFor(key) {
                    var own = current && current.filterDefs && current.filterDefs[key];
                    return own || ((DATA && DATA.filterDefs) || {})[key];
                }

                function fieldHtml(key, def) {
                    if (!def) { return ''; }
                    if (def.type === 'dateRange') {
                        return '<div class="rpt-f">' +
                                '<label for="f_' + esc(key) + '_from">' + esc(def.label || 'จากวันที่') + '</label>' +
                                '<div class="rpt-range">' +
                                    '<input type="text" class="rpt-in ods-date" id="f_' + esc(key) + '_from" placeholder="dd/mm/yyyy" value="' + esc(isoToMdy(resolveDefaultDate(def.defaultFrom))) + '"/>' +
                                    '<span>' + esc(def.labelTo || 'ถึง') + '</span>' +
                                    '<input type="text" class="rpt-in ods-date" id="f_' + esc(key) + '_to" placeholder="dd/mm/yyyy" value="' + esc(isoToMdy(resolveDefaultDate(def.defaultTo))) + '"/>' +
                                '</div>' +
                            '</div>';
                    }
                    /* def.source = ดึงตัวเลือกจาก master data จริง (โหลดหลัง render ใน loadDynOptions) */
                    var ph = def.source ? 'กำลังโหลด...' : 'เลือก';
                    var opts = '<option value="">' + esc(ph) + '</option>' + (def.options || []).map(function (o) {
                        return '<option value="' + esc(o.value) + '">' + esc(o.label) + '</option>';
                    }).join('');
                    return '<div class="rpt-f">' +
                            '<label for="f_' + esc(key) + '">' + esc(def.label || key) + '</label>' +
                            '<select class="rpt-in" id="f_' + esc(key) + '">' + opts + '</select>' +
                        '</div>';
                }

                /* โหลดตัวเลือกจาก master data จริงของระบบ (แคชไว้ ไม่ยิงซ้ำเวลาสลับรายงาน) */
                var DYN_CACHE = {};
                function loadDynOptions() {
                    (current.filters || []).forEach(function (k) {
                        var def = defFor(k);
                        if (!def || !def.source) { return; }
                        var sel = $('f_' + k);
                        if (!sel) { return; }
                        var url = CTX + def.source;
                        var vf = def.valueField || 'code';
                        /* labelField ใส่เป็น array ได้ เช่น ["code","name"] -> "SA-001 ธาวิน ..."
                           (พนักงานขาย/ผู้รับผิดชอบ ชื่อซ้ำกันได้ ระบบส่วนอื่นจึงโชว์รหัสนำหน้าเหมือนกัน) */
                        var lf = def.labelField || 'name';
                        var lfs = Object.prototype.toString.call(lf) === '[object Array]' ? lf : [lf];
                        function fill(list) {
                            if ($('f_' + k) !== sel) { return; }   /* สลับรายงานไปแล้ว อย่าเติมผิดที่ */
                            sel.options[0].textContent = 'เลือก';
                            list.forEach(function (it) {
                                var o = document.createElement('option');
                                o.value = String(it[vf] == null ? '' : it[vf]);
                                var txt = lfs.map(function (f) { return it[f] == null ? '' : String(it[f]); })
                                        .filter(function (x) { return x !== ''; }).join(' ');
                                o.textContent = txt || String(it[vf] || '');
                                sel.appendChild(o);
                            });
                        }
                        if (DYN_CACHE[url]) { fill(DYN_CACHE[url]); return; }
                        env.fetch(url, {credentials: 'same-origin', headers: {'Accept': 'application/json'}})
                            .then(function (r) { return r.ok ? r.json() : Promise.reject(r.status); })
                            .then(function (j) {
                                /* ★ 07/10/2026 — ตัวเลือกมาจาก servlet 2 แบบที่ "รูปคำตอบไม่เหมือนกัน"
                                   /board/chat-master-data : ส่งต่อคำตอบของ API ทั้งก้อน -> {status,message,result:[...]}
                                   /board/employees        : คืนอาร์เรย์ล้วน -> [ {...}, {...} ]
                                   โค้ดเดิมอ่านแต่ j.result ดรอปดาวน์ "พนักงาน/ผู้รับผิดชอบ" จึงว่างเปล่า
                                   ทั้งที่ servlet ตอบ 200 พร้อมข้อมูลจริง (ดู access log: 200 24796 bytes)
                                   รับทั้งสองรูปไว้เลย เผื่อ servlet ตัวอื่นที่เพิ่มทีหลังเป็นแบบไหนก็ได้ */
                                var list = Array.isArray(j) ? j : ((j && j.result) || []);
                                DYN_CACHE[url] = list;
                                fill(list);
                            })
                            .catch(function (err) {
                                console.error('[report] โหลดตัวเลือก ' + k + ' ไม่สำเร็จ:', err);
                                if ($('f_' + k) === sel) { sel.options[0].textContent = 'โหลดตัวเลือกไม่สำเร็จ'; }
                            });
                    });
                }

                function renderSide() {
                    var box = $('rptSide');
                    if (!box) { return; }
                    if (!current) {
                        box.innerHTML = '<div class="rpt-side-empty">' +
                                '<i class="fa-regular fa-file-lines"></i>' +
                                '<span>เลือกรายงานจากรายการด้านซ้าย<br/>เพื่อกำหนดเงื่อนไขและเรียกดู</span></div>';
                        return;
                    }
                    var fields = (current.filters || []).map(function (k) { return fieldHtml(k, defFor(k)); }).join('');
                    box.innerHTML =
                        '<div class="rpt-side-title"><span class="c">' + esc(current.code) + '</span> ' + esc(current.name) + '</div>' +
                        fields +
                        '<div class="rpt-acts">' +
                            '<button type="button" class="rpt-btn" id="rptClear">ล้างค่า</button>' +
                            '<button type="button" class="rpt-btn rpt-btn-primary" id="rptRun">' +
                                '<i class="fa-regular fa-eye"></i> เรียกดู</button>' +
                        '</div>';

                    var clear = $('rptClear');
                    if (clear) { clear.addEventListener('click', clearFilters); }
                    var run = $('rptRun');
                    if (run) { run.addEventListener('click', runReport); }
                    loadDynOptions();
                }

                function clearFilters() {
                    if (!current) { return; }
                    (current.filters || []).forEach(function (k) {
                        var def = defFor(k);
                        if (!def) { return; }
                        if (def.type === 'dateRange') {
                            var a = $('f_' + k + '_from'), b = $('f_' + k + '_to');
                            if (a) { a.value = isoToMdy(resolveDefaultDate(def.defaultFrom)); }   /* ช่องแสดงเป็น dd/MM/yyyy */
                            if (b) { b.value = isoToMdy(resolveDefaultDate(def.defaultTo)); }
                        } else {
                            var s = $('f_' + k);
                            if (s) { s.value = ''; }
                        }
                    });
                    toast('ล้างค่าเงื่อนไขแล้ว');
                }

                function collectFilters() {
                    var out = {};
                    (current.filters || []).forEach(function (k) {
                        var def = defFor(k);
                        if (!def) { return; }
                        if (def.type === 'dateRange') {
                            /* ช่องเก็บ dd/MM/yyyy แต่ส่งออกเป็น yyyy-MM-dd ให้เหมือนเดิม
                               (servlet ตรวจรูปแบบ yyyy-MM-dd อยู่ ดู ReportPdfServlet.sqlDate) */
                            out[k] = {
                                from: mdyToIso(($('f_' + k + '_from') || {}).value),
                                to: mdyToIso(($('f_' + k + '_to') || {}).value)
                            };
                        } else {
                            out[k] = ($('f_' + k) || {}).value || '';
                        }
                    });
                    return out;
                }

                /* ★ ประกอบ URL ของ ReportPdfServlet — ชื่อ param ตรงกับ key ของตัวกรอง
                   (dateRange ส่งเป็น dateRange_from / dateRange_to) servlet ฝั่ง server เอาไปแปลง
                   เป็น externalSQLWhere ตามคอลัมน์ที่ตั้งไว้ใน config ของรายงานนั้น */
                function reportPdfUrl(code, f) {
                    var q = ['code=' + encodeURIComponent(code)];
                    Object.keys(f).forEach(function (k) {
                        var v = f[k];
                        if (v && typeof v === 'object') {
                            if (v.from) { q.push(encodeURIComponent(k + '_from') + '=' + encodeURIComponent(v.from)); }
                            if (v.to) { q.push(encodeURIComponent(k + '_to') + '=' + encodeURIComponent(v.to)); }
                        } else if (v) {
                            q.push(encodeURIComponent(k) + '=' + encodeURIComponent(v));
                        }
                    });
                    return CTX + '/report-pdf?' + q.join('&');
                }

                function runReport() {
                    if (!current) { return; }
                    if (!canReport(current.code)) {   /* ★ ไม่มีสิทธิ์ = ไม่ยิง servlet เลย */
                        toast('ไม่มีสิทธิ์เรียกดูรายงาน ' + current.code);
                        return;
                    }
                    var f = collectFilters();
                    /* รายงานที่ยังไม่ได้ต่อกับระบบรายงานเดิม (pdf ไม่เป็น true ใน json) — คงพฤติกรรม
                       ตัวอย่างเดิมไว้ ไม่เปิดแท็บเปล่าให้ผู้ใช้เจอหน้า error */
                    if (!current.pdf) {
                        console.log('[report] ' + current.code, f);
                        toast('รายงาน ' + current.code + ' ยังไม่ได้ต่อกับระบบรายงาน — ดูเงื่อนไขที่เลือกได้ใน Console');
                        return;
                    }
                    /* ★ 19/08/2026 — ตัวกรองที่ระบบรายงานเดิม "บังคับต้องเลือก" (filterDefs[..].required)
                       เช่น SUN-LD-06 ใบประวัติการติดตาม ที่ต้องระบุลูกค้า ไม่งั้น engine ตอบ 0 ไบต์
                       แล้วผู้ใช้จะเจอแท็บเปล่า ๆ โดยไม่รู้สาเหตุ — กันไว้ตั้งแต่ก่อนเปิดแท็บ */
                    var missing = (current.filters || []).filter(function (k) {
                        var def = defFor(k);   /* เคารพ filterDefs ที่รายงานทับไว้เอง */
                        return def && def.required && !f[k];
                    });
                    if (missing.length) {
                        var names = missing.map(function (k) {
                            return (defFor(k) || {}).label || k;
                        });
                        toast('กรุณาเลือก ' + names.join(', ') + ' ก่อนเรียกรายงาน ' + current.code);
                        return;
                    }
                    /* เปิดแท็บใหม่ให้ browser แสดง PDF เอง (แนวเดียวกับปุ่ม "เปิด PDF" ของ gold-x
                       ที่ใช้ form target="_blank") — ต้องเปิดใน handler ของ click ไม่งั้นโดน popup blocker */
                    var url = reportPdfUrl(current.code, f);
                    console.log('[report] เปิด PDF: ' + url);
                    var w = env.open(url, '_blank');
                    if (!w) {
                        toast('เบราว์เซอร์บล็อกการเปิดแท็บใหม่ — อนุญาต popup ของเว็บนี้แล้วลองอีกครั้ง');
                        return;
                    }
                    /* บางรายงานยังต่อกับระบบรายงานเดิมไม่ได้ตรง ๆ (ดู .mode ใน config) — บอกผู้ใช้
                       ให้ตรงกับสิ่งที่จะเกิดขึ้นจริงในแท็บใหม่ ไม่ใช่บอกว่ากำลังสร้าง PDF */
                    toast(current.pdfNote || ('กำลังเรียกรายงาน ' + current.code + ' ...'));
                }

                /* ★ 21/08: user ขอให้ toast มุมล่างกลางจอเปลี่ยนเป็นแจ้งเตือนกลางจอแบบ swal ทั้งระบบ */
                function toast(msg) {
                    if (env.swal) {
                        env.swal({ text: msg, icon: 'info', timer: 3000, buttons: false });
                    }
                }

                function boot() {
                    var s = $('rptSearch');
                    if (s) {
                        s.addEventListener('input', function () { kw = s.value; renderGroups(); });
                    }
                    env.fetch(RPT_DATA_URL, { credentials: 'same-origin' })
                        .then(function (r) { return r.ok ? r.json() : Promise.reject(r.status); })
                        .then(function (j) {
                            DATA = j;
                            renderGroups();
                            renderSide();
                        })
                        .catch(function (err) {
                            console.error('[report] โหลดข้อมูลรายงานไม่สำเร็จ:', err);
                            var box = $('rptGroups');
                            if (box) {
                                box.innerHTML = '<div class="rpt-card"><div class="rpt-empty">' +
                                        'โหลดรายการรายงานไม่สำเร็จ (resources/mock/report_mock.json)</div></div>';
                            }
                        });
                }
                if (readyState === 'loading') {
                    onReady(boot);
                } else {
                    boot();
                }
            })();
  /* the entry points of the inline handlers and of the window.* functions */
  
  var EXPORTED = [];

  /* "the document has been parsed": DOMContentLoaded handlers in the order they were registered, then "load" */
  readyState = 'interactive';
  runQueue(readyQueue, 'DOMContentLoaded');
  readyState = 'complete';
  tmo(function () { runQueue(loadQueue, 'load'); }, 0);

  return function destroy() {
    destroyed = true;
    disposers.splice(0).forEach(function (d) { d(); });
    timers.splice(0).forEach(function (h) { clearTimeout(h); });
    observers.splice(0).forEach(function (o) { o.disconnect(); });
    EXPORTED.forEach(function (n) { try { delete window[n]; } catch (e) { window[n] = undefined; } });
  };
}
